using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static MatchEngine GvgGame(int seed=42){var a=DeckRules.ForCurrentPlay(catalog,matchRules.TrainingDeck("MAGE"));var b=DeckRules.ForCurrentPlay(catalog,matchRules.TrainingDeck("WARRIOR"));var g=new MatchEngine(catalog,a,b,seed,true);g.MarkMulliganCompleteForTests();foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}return g;}
 static int GvgHand(MatchEngine g,string card,int seat=0){int n=id++;g.Players[seat].Hand.Add(new HandCard{Id=n,CardId=card,Generated=true});return n;}
 static void GvgKill(MatchEngine g,BattleUnit unit){unit.DamageTaken=unit.MaxHealth;g.Cleanup();}
 static void Gvg(){GvgLibrary();GvgBattlecries();GvgTriggers();GvgDeaths();GvgCombat();GvgParts();}
 static void GvgLibrary(){
  var pool=catalog.Pool(GvgRules.SetId);var cards=catalog.Deckable(pool).Where(c=>c.SetId==GvgRules.SetId).ToArray();Check(cards.Length==51&&cards.All(c=>c.CardClass=="NEUTRAL"&&matchRules.Supports(c)),"All 51 new GvG Neutral cards are supported");Check(catalog.Deckable(pool).Count==535&&catalog.Deckable(catalog.Pool("classic-2014")).Count==382&&catalog.Deckable(catalog.Pool("naxxramas-2014")).Count==412,"New 463-card pool leaves frozen Classic and Naxx counts intact");Check(catalog.Cards.Values.Count(c=>c.SetId==GvgRules.SetId&&!c.Collectible)==10,"Exactly seven Parts and three minion tokens are noncollectible");
  Check(catalog.Card("GVG_006").Cost==2&&catalog.Card("GVG_006").Attack==2&&catalog.Card("GVG_006").Health==3&&catalog.Card("GVG_109").Cost==4&&catalog.Card("GVG_109").Attack==4&&catalog.Card("GVG_114").Cost==8,"Original launch values restored instead of modern nerfs/buffs");
  var old=matchRules.TrainingDeck("MAGE");string code=DeckCode.Encode(catalog,old);var promoted=DeckRules.ForCurrentPlay(catalog,old);Check(promoted.PoolId==pool.Id&&DeckCode.Encode(catalog,old)==code&&old.PoolId=="classic-2014","Old decks promote at runtime without modifying their stored code");Check(DeckCode.Decode(catalog,DeckCode.Encode(catalog,promoted),pool.Id).Cards.OrderBy(p=>p.Key).SequenceEqual(promoted.Cards.OrderBy(p=>p.Key)),"New pool deck code roundtrips");
  foreach(var card in cards){var g=GvgGame();g.Summon(0,"VAN_DS1_175");g.Summon(0,"GVG_044");var enemy=g.Summon(1,"VAN_DS1_175");for(int n=0;n<6;n++)GvgHand(g,"VAN_CS2_182",1);var target=card.Id=="GVG_108"?new MatchTarget(0,g.Players[0].Board[0].Id):card.Id=="GVG_120"?new MatchTarget(1,enemy.Id):null;Check(g.Play(0,GvgHand(g,card.Id),target).Success,"Every neutral can be played through engine: "+card.Id);}
  bool inArena=false;for(int seed=0;seed<4;seed++){var session=new ArenaDraftSession(catalog,seed,matchRules.Supports);var v=session.View(0);session.Pick(0,v.Session,v.Revision,0);for(int n=0;n<30;n++){v=session.View(0);inArena|=v.Choices.Any(c=>catalog.Card(c).SetId==GvgRules.SetId);session.Pick(0,v.Session,v.Revision,0);}}Check(inArena,"New neutral cards appear in Arena offers automatically");
  var sealedGame=new SealedSession(catalog,2901,matchRules.Supports);var sealedView=sealedGame.View(0);sealedGame.Act(0,sealedView.Session,sealedView.Revision,"class",sealedView.Classes[0]);sealedView=sealedGame.View(0);sealedGame.Act(0,sealedView.Session,sealedView.Revision,"open-all");Check(sealedGame.View(0).Pool.Keys.Any(c=>catalog.Card(c).SetId==GvgRules.SetId),"New neutral cards enter sealed packs without changing pack probabilities");
  var unknown=new CardRecord{Id="GVG_future",BaseId="GVG_future",EffectId="GVG_future",SetId=GvgRules.SetId,Type="MINION"};Check(!matchRules.Supports(unknown),"Future cards in same package do not silently become blank supported minions");
 }
 static void GvgBattlecries(){
  var g=GvgGame();g.Players[0].Health=10;g.Play(0,GvgHand(g,"GVG_069"));Check(g.Players[0].Health==18,"Healbot heals own hero eight");
  g=GvgGame();g.Summon(0,"VAN_EX1_591");g.Players[0].Health=10;g.Play(0,GvgHand(g,"GVG_069"));Check(g.Players[0].Health==2,"Healbot uses shared Auchenai conversion");
  g=GvgGame();g.Play(0,GvgHand(g,"GVG_102"));Check(g.Players[0].Hand.Count==0&&g.Players[0].Board.Single().MaxHealth==3,"Tinkertown needs another friendly Mech");g=GvgGame();g.Summon(0,"GVG_044");g.Play(0,GvgHand(g,"GVG_102"));Check(g.Players[0].Board.Last().MaxHealth==4&&g.Players[0].Hand.Count==1&&GvgRules.Parts.Contains(g.Players[0].Hand[0].CardId),"Tinkertown buffs itself and grants a private Part");
  g=GvgGame();var egg=g.Summon(1,"FP1_007");var muted=g.Summon(1,"GVG_076");g.Silence(new MatchTarget(1,muted.Id));g.Play(0,GvgHand(g,"GVG_097"));Check(g.AttackValue(g.Players[0].Board.Single())==3&&g.Players[0].Board.Single().Health==4,"Exorcist counts only enemy active deathrattles");
  g=GvgGame();var beast=g.Summon(1,"VAN_DS1_175");var mech=g.Summon(1,"GVG_044");int hermit=GvgHand(g,"GVG_120"),mana=g.Players[0].Mana;Check(!g.Play(0,hermit,new MatchTarget(1,mech.Id)).Success&&g.Players[0].Mana==mana,"Hemet rejects non-Beasts before payment");Check(g.Play(0,hermit,new MatchTarget(1,beast.Id)).Success&&!g.Players[1].Board.Contains(beast),"Hemet destroys selected Beast");
  g=GvgGame();g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_EX1_561");g.Play(0,GvgHand(g,"GVG_092"));Check(g.Players[0].Hand.Single().CardId=="GVG_092t"&&g.Players[0].Hand.Single().Generated,"Experiment transforms drawn minion into Chicken");g=GvgGame();g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_CS2_029");g.Play(0,GvgHand(g,"GVG_092"));Check(g.Players[0].Hand.Single().CardId=="VAN_CS2_029","Experiment keeps a drawn spell");
  g=GvgGame();var before=g.Summon(0,"GVG_044");g.Summon(0,"GVG_044");g.Play(0,GvgHand(g,"GVG_107"));Check(g.Players[0].Board.Take(2).All(u=>u.Windfury||u.Taunt||u.Shield)&&!g.Players[0].Board.Last().Windfury&&!g.Players[0].Board.Last().Shield,"Enhance-o assigns one keyword to each other friendly minion");
  g=GvgGame();g.Play(0,GvgHand(g,"GVG_110"));Check(g.Players[0].Board.Select(u=>u.CardId).SequenceEqual(new[]{"GVG_110t","GVG_110","GVG_110t"}),"Boom puts one Bot on either side");
  g=GvgGame();for(int i=0;i<5;i++)g.Summon(0,"GVG_044");g.Play(0,GvgHand(g,"GVG_110"));Check(g.Players[0].Board.Count==7&&g.Players[0].Board.Count(u=>u.CardId=="GVG_110t")==1,"Boom obeys seven-slot limit");
  g=GvgGame();g.Equip(0,"VAN_CS2_106");g.Equip(1,"VAN_CS2_106");g.Play(0,GvgHand(g,"GVG_119"));Check(g.Players.All(p=>p.WeaponDurability>0)&&g.Graveyard.Count(e=>e.Reason==GraveyardReason.WeaponReplaced)==2,"Blingtron equips both heroes through replacement and weapon-death infrastructure");
  g=GvgGame();var body=g.Summon(0,"GVG_044");g.Buff(new MatchTarget(0,body.Id),5,5);int old=body.Id;g.Play(0,GvgHand(g,"GVG_108"),new MatchTarget(0,old));var changed=g.Players[0].Board[0];Check(changed.Id!=old&&g.Card(changed.CardId).Cost==3&&changed.BuffAttack==0&&changed.BuffHealth==0,"Recombobulator uses printed cost and clears old buffs");
  g=GvgGame();g.Players[0].Health=g.Players[1].Health=100;g.Play(0,GvgHand(g,"GVG_090"));Check(g.Players.Sum(p=>p.Health)==194&&g.Players[0].Board.Single().DamageTaken==0,"Madder Bomber deals six sequential points excluding itself");
  g=GvgGame();var victim=g.Summon(1,"GVG_044");g.Play(0,GvgHand(g,"GVG_099"));Check(!g.Players[1].Board.Contains(victim)&&g.Players[1].Health==30,"Bomb Lobber deals four to a random enemy minion only");
  g=GvgGame();g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_287"});g.Play(0,GvgHand(g,"GVG_074"));Check(g.Players[0].SecretCount==1&&g.Players[1].SecretCount==0&&g.SecretCards(0).Single()=="VAN_EX1_287","Kezan transfers secret ownership without revealing it");Check(g.VisualEvents.Any(e=>e.Kind=="secret-stolen"&&e.RecipientSeat==0),"Kezan notice has its own private event type instead of Scientist wording");Check(!LanProtocol.View(g,1,"gvg",1).OwnSecrets.Any()&&!LanProtocol.View(g,1,"gvg",1).VisualEvents.Any(e=>e.CardId=="VAN_EX1_287"),"Stolen secret identity is never sent back to its former owner as new private state");
 }
 static void GvgTriggers(){
  var g=GvgGame();int card=GvgHand(g,"GVG_044");var warper=g.Summon(0,"GVG_006");var warper2=g.Summon(0,"GVG_006");Check(g.HandCost(0,g.Players[0].Hand.Single(h=>h.Id==card))==1,"Mechwarpers stack reductions");g.Silence(new MatchTarget(0,warper.Id));Check(g.HandCost(0,g.Players[0].Hand.Single(h=>h.Id==card))==2,"Silence removes cost aura");var cog=g.Summon(0,"GVG_013");Check(g.AttackValue(cog)==3,"Cogmaster sees friendly Mechs");g.Players[0].Board.Remove(warper);g.Players[0].Board.Remove(warper2);Check(g.AttackValue(cog)==1,"Cogmaster loses attack when last friendly Mech leaves");
  g=GvgGame();var sapper=g.Summon(0,"GVG_095");for(int i=0;i<6;i++)GvgHand(g,"VAN_CS2_182",1);Check(g.AttackValue(sapper)==6,"Sapper gains four at six enemy cards");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,0,"gvg",1)));Check(view.AttackValue(view.Players[0].Board.Single())==6&&view.Players[1].Hand.Count==0,"Sapper computes from public hand count without hand identity");g.Players[1].Hand.RemoveAt(0);Check(g.AttackValue(sapper)==2,"Sapper attack immediately falls below threshold");
  g=GvgGame();var micro=g.Summon(0,"GVG_103");g.EndTurn();g.EndTurn();Check(g.AttackValue(micro)==3,"Micro gains one at each player's turn start");g.Silence(new MatchTarget(0,micro.Id));g.EndTurn();Check(g.AttackValue(micro)==1,"Silenced Micro stops gaining attack");
  g=GvgGame();var trogg=g.Summon(1,"GVG_067");var burly=g.Summon(1,"GVG_068");g.Summon(1,"GVG_118");g.Play(0,GvgHand(g,"GAME_COIN"));Check(g.AttackValue(trogg)==3&&g.AttackValue(burly)==5&&g.Players[1].Board.Count(u=>u.CardId=="GVG_068")==2,"Enemy spell grows Troggs and summons one Burly");
  g=GvgGame();var gaz=g.Summon(0,"GVG_117");g.Summon(0,"VAN_EX1_608");g.Play(0,GvgHand(g,"VAN_CS2_024"),new MatchTarget(1));Check(g.Players[0].Hand.Count==1&&g.Card(g.Players[0].Hand.Single().CardId).Race=="MECHANICAL","Gazlowe uses actual one-mana paid cost after reduction");g.Players[0].Hand.Clear();g.Play(0,GvgHand(g,"PART_001"),new MatchTarget(0,gaz.Id));Check(g.Players[0].Hand.Count==0,"Zero-cost reduced Part does not trigger Gazlowe");
  g=GvgGame();g.Summon(0,"GVG_104");g.Play(0,GvgHand(g,"GVG_103"));var played=g.Players[0].Board.Last();Check(g.AttackValue(played)==3&&played.MaxHealth==4,"Hobgoblin buffs a played one-Attack minion");var summoned=g.Summon(0,"GVG_103");Check(g.AttackValue(summoned)==1&&summoned.MaxHealth==2,"Hobgoblin does not buff merely summoned minions");
  g=GvgGame();g.Summon(0,"GVG_104");g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_379"});g.Play(0,GvgHand(g,"GVG_103"));var repent=g.Players[0].Board.Last();Check(g.AttackValue(repent)==3&&repent.Health==1&&repent.MaxHealth==1,"Hobgoblin buffs before Repentance so life is set to one last");
  g=GvgGame();g.Summon(0,"GVG_104");g.Summon(0,"GVG_104");g.Play(0,GvgHand(g,"GVG_103"));Check(g.AttackValue(g.Players[0].Board.Last())==5&&g.Players[0].Board.Last().MaxHealth==6,"Two Hobgoblins both recognize original one-Attack played card");
  g=GvgGame();g.Summon(0,"GVG_075");g.Summon(0,"VAN_NEW1_018");Check(g.Players[1].Health==28,"Ship's Cannon fires on friendly Pirate summon");g.Summon(1,"VAN_NEW1_018");Check(g.Players[1].Health==28,"Enemy Pirate does not trigger Cannon");
  g=GvgGame();var reaver=g.Summon(1,"GVG_016");g.Players[1].Deck.Clear();g.Players[1].Deck.AddRange(new[]{"VAN_CS2_182","VAN_CS2_029","GVG_044","GVG_110"});g.Play(0,GvgHand(g,"GAME_COIN"));Check(g.Players[1].Deck.SequenceEqual(new[]{"GVG_110"})&&g.GraveyardFor(1,GraveyardReason.RemovedFromDeck).Length==3&&g.Players[1].Fatigue==0,"Fel Reaver removes exactly top three, with no draw or fatigue");g.Silence(new MatchTarget(1,reaver.Id));g.Play(0,GvgHand(g,"GAME_COIN"));Check(g.Players[1].Deck.Count==1,"Silenced Fel Reaver stops burning");
  g=GvgGame();var junk=g.Summon(0,"GVG_106");var sheep=g.Summon(0,"GVG_076");GvgKill(g,sheep);Check(g.AttackValue(junk)==3&&junk.MaxHealth==7&&junk.DamageTaken==2,"Junkbot gains before dead Mech's deathrattle resolves");
  g=GvgGame();var therma=g.Summon(0,"GVG_116");var enemy=g.Summon(1,"GVG_044");GvgKill(g,enemy);Check(g.Players[0].Board.Any(u=>u.CardId=="VAN_EX1_029"),"Thermaplugg summons Leper for enemy death");
  g=GvgGame();g.Summon(0,"GVG_094");g.Players[0].Deck.Clear();g.Players[0].Deck.AddRange(Enumerable.Repeat("VAN_CS2_182",10));g.EndTurn();Check(g.Players[0].Hand.Count==3,"Jeeves refills active player's hand at own end");g.Players[1].Hand.Clear();g.EndTurn();Check(g.Players[1].Hand.Count==3,"Jeeves also refills opponent at their end");
  g=GvgGame();g.Summon(0,"GVG_089");g.Players[0].Health=10;g.ArmSecret(0,new HandCard{Id=id++,CardId="VAN_EX1_287"});g.EndTurn();Check(g.Players[0].Health==14,"Illuminator heals only own end while a secret is controlled");
 }
 static void GvgDeaths(){
  foreach(string key in new[]{"GVG_096","GVG_105","GVG_114"}){var g=GvgGame();var dead=g.Summon(0,key);var right=g.Summon(0,"GVG_044");GvgKill(g,dead);var summoned=g.Players[0].Board[0];Check(summoned.Id!=right.Id&&(key=="GVG_114"?g.Card(summoned.CardId).Rarity=="LEGENDARY":g.Card(summoned.CardId).Cost==(key=="GVG_096"?2:4)),"Random deathrattle respects filter and original position: "+key);}
  var game=GvgGame();game.Summon(0,"FP1_031");var gnome=game.Summon(0,"GVG_082");GvgKill(game,gnome);Check(game.Players[0].Hand.Count==2&&game.Players[0].Hand.All(h=>GvgRules.Parts.Contains(h.CardId)),"Baron doubles Part deathrattle");
  game=GvgGame();gnome=game.Summon(0,"GVG_082");game.Silence(new MatchTarget(0,gnome.Id));GvgKill(game,gnome);Check(game.Players[0].Hand.Count==0,"Silence suppresses GvG deathrattles");
  game=GvgGame();var yeti=game.Summon(0,"GVG_078");GvgKill(game,yeti);Check(game.Players.All(p=>p.Hand.Count==1&&GvgRules.Parts.Contains(p.Hand[0].CardId)),"Mechanical Yeti gives independent Parts to each player");
  game=GvgGame();game.Play(0,GvgHand(game,"GVG_115"));Check(game.Players[0].Hand.Count==1,"Toshley grants Part on battlecry");GvgKill(game,game.Players[0].Board.Single());Check(game.Players[0].Hand.Count==2,"Toshley grants Part again on death");
  game=GvgGame();var sheep=game.Summon(0,"GVG_076");var egg=game.Summon(1,"FP1_007");GvgKill(game,sheep);Check(game.Players[1].Board.Single().CardId=="FP1_007t"&&game.Players[1].Board[0].DamageTaken==0,"Sheep does not hit replacement spawned by subsequent deathrattle");
  for(int seed=0;seed<12;seed++){game=GvgGame(seed);var bomb=game.Summon(0,"GVG_110t");int hp=game.Players[1].Health;GvgKill(game,bomb);Check(hp-game.Players[1].Health>=1&&hp-game.Players[1].Health<=4,"Boom Bot damage range one through four");}
  game=GvgGame();game.Summon(0,"GVG_111");game.Summon(0,"GVG_044");game.Summon(0,"GVG_093");game.EndTurn();game.EndTurn();Check(game.Players[0].Board.Single().CardId=="GVG_111t"&&game.GraveyardFor(0,GraveyardReason.MinionDied).Length==3,"Mimiron destroys all friendly Mechs and summons V-07-TR-0N at own start");
  game=GvgGame();game.Summon(0,"GVG_111");game.Summon(0,"GVG_044");game.EndTurn();game.EndTurn();Check(!game.Players[0].Board.Any(u=>u.CardId=="GVG_111t"),"Mimiron needs three living Mechs");
 }
 static void GvgCombat(){
  var g=GvgGame();var voltron=g.Summon(0,"GVG_111t");g.Players[1].Health=100;for(int n=0;n<4;n++)Check(g.Attack(0,voltron.Id,new MatchTarget(1)).Success,"Mega Windfury allows each of four Charge attacks");Check(g.Players[1].Health==84&&!g.Attack(0,voltron.Id,new MatchTarget(1)).Success,"V-07-TR-0N cannot attack fifth time");g.Silence(new MatchTarget(0,voltron.Id));Check(g.MinionAttackLimit(voltron)==1&&!g.HasCharge(voltron),"Silence removes native Charge and Mega Windfury");
  g=GvgGame();var reaper=g.Summon(0,"GVG_113");reaper.SummonTurn=0;var left=g.Summon(1,"VAN_CS2_182");var middle=g.Summon(1,"VAN_CS2_182");var right=g.Summon(1,"VAN_CS2_182");g.Buff(new MatchTarget(1,middle.Id),0,10);g.Attack(0,reaper.Id,new MatchTarget(1,middle.Id));Check(left.Health<=0&&right.Health<=0&&middle.DamageTaken==6&&reaper.DamageTaken==4,"Foe Reaper cleaves both neighbors but receives retaliation only from main target");
  bool redirected=false,normal=false;for(int seed=0;seed<30;seed++){g=GvgGame(seed);var ogre=g.Summon(0,"GVG_065");ogre.SummonTurn=0;g.Summon(1,"GVG_044");g.Attack(0,ogre.Id,new MatchTarget(1));var attack=g.VisualEvents.Last(e=>e.Kind=="attack");redirected|=attack.TargetUnitId!=0;normal|=attack.TargetUnitId==0;Check(g.Players[0].Board.Contains(ogre)&&ogre.AttacksUsed==1,"Ogre attack is consumed once whether redirected or not");}Check(redirected&&normal,"Ogre redirection has both random outcomes");
  g=GvgGame();var giant=GvgHand(g,"GVG_121");for(int n=0;n<6;n++)GvgHand(g,"VAN_CS2_182",1);Check(g.HandCost(0,g.Players[0].Hand.Single(h=>h.Id==giant))==6,"Clockwork Giant discounts by opponent hand count");
  g=GvgGame();var nullifier=g.Summon(1,"GVG_091");Check(!g.Play(0,GvgHand(g,"VAN_CS2_029"),new MatchTarget(1,nullifier.Id)).Success,"Nullifier rejects spells");g.Players[0].ClassId="MAGE";Check(!g.HeroPower(0,new MatchTarget(1,nullifier.Id)).Success,"Nullifier rejects hero powers");Check(g.Play(0,GvgHand(g,"VAN_EX1_048"),new MatchTarget(1,nullifier.Id)).Success&&nullifier.Silenced,"Nullifier still allows targeted minion battlecry");
 }
 static void GvgParts(){
  var g=GvgGame();var body=g.Summon(0,"GVG_044");var target=new MatchTarget(0,body.Id);g.Play(0,GvgHand(g,"PART_001"),target);g.Play(0,GvgHand(g,"PART_007"),target);Check(g.AttackValue(body)==4&&body.MaxHealth==5,"Health and Attack Parts buff chosen minion");g.Play(0,GvgHand(g,"PART_003"),target);Check(body.Taunt,"Taunt Part sets Taunt");g.Play(0,GvgHand(g,"PART_005"),target);Check(body.Frozen,"Freeze Part freezes chosen minion");g.Play(0,GvgHand(g,"PART_006"),target);Check(g.AttackValue(body)==5&&body.Health==4,"Reversing Switch swaps current attack and health");g.Play(0,GvgHand(g,"PART_004"),target);Check(body.Stealth,"Cloaking Part grants temporary Stealth");g.EndTurn();Check(body.Stealth,"Temporary Stealth lasts through enemy turn");g.EndTurn();Check(!body.Stealth,"Cloaking Part expires at next own turn start");g.Play(0,GvgHand(g,"PART_002"),target);Check(!g.Players[0].Board.Contains(body)&&g.Players[0].Hand.Any(h=>h.CardId=="GVG_044"),"Time Rewinder returns own minion and removes battlefield buffs");
  g=GvgGame();var native=g.Summon(0,"GVG_081");g.Play(0,GvgHand(g,"PART_004"),new MatchTarget(0,native.Id));g.EndTurn();g.EndTurn();Check(native.Stealth,"Applying Cloaking Field does not expire native permanent Stealth");
  g=GvgGame();for(int i=0;i<10;i++)GvgHand(g,"VAN_CS2_182");g.GiveGvgPart(0);Check(g.Players[0].Hand.Count==10,"Generated Parts obey hand cap");
 }
}

